package main

import (
	"fmt"
	"net/http"
	"sync"
	"unsafe"
)

// #include <stdlib.h>
import "C"

type SessionCache struct {
	mu       sync.Mutex
	sessions map[string]*SessionData
}

type SessionData struct {
	ptr    unsafe.Pointer
	active bool
	refCnt int
}

var cache = &SessionCache{
	sessions: make(map[string]*SessionData),
}

func (sc *SessionCache) CreateSession(id string, size int) {
	sc.mu.Lock()
	defer sc.mu.Unlock()
	ptr := C.malloc(C.size_t(size))
	sc.sessions[id] = &SessionData{ptr: ptr, active: true, refCnt: 1}
}

func (sc *SessionCache) GetSession(id string) *SessionData {
	sc.mu.Lock()
	defer sc.mu.Unlock()
	if s, ok := sc.sessions[id]; ok {
		s.refCnt++
		return s
	}
	return nil
}

// DestroySession frees the underlying C memory.
// BUG: Does not check if already freed, does not remove from map atomically
// with the free. A concurrent request can obtain the pointer between the
// free and the map deletion, then call DestroySession again -> double-free.
func (sc *SessionCache) DestroySession(id string) error {
	sc.mu.Lock()
	s, ok := sc.sessions[id]
	if !ok {
		sc.mu.Unlock()
		return fmt.Errorf("session not found")
	}
	// Release lock before expensive free (simulating real-world pattern)
	sc.mu.Unlock()

	// TOCTOU: another goroutine can grab the session here
	C.free(s.ptr)
	s.ptr = nil

	sc.mu.Lock()
	delete(sc.sessions, id)
	sc.mu.Unlock()
	return nil
}

func createHandler(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	if id == "" {
		http.Error(w, "missing id", 400)
		return
	}
	cache.CreateSession(id, 1024)
	w.WriteHeader(201)
	fmt.Fprintf(w, "created session %s\n", id)
}

func destroyHandler(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	if id == "" {
		http.Error(w, "missing id", 400)
		return
	}
	if err := cache.DestroySession(id); err != nil {
		http.Error(w, err.Error(), 404)
		return
	}
	w.WriteHeader(200)
	fmt.Fprintf(w, "destroyed session %s\n", id)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/session/create", createHandler)
	http.HandleFunc("/session/destroy", destroyHandler)
	http.HandleFunc("/health", healthHandler)
	fmt.Println("listening on :8080")
	http.ListenAndServe(":8080", nil)
}
